WITH store_price AS ( SELECT ss_item_sk, AVG(ss_list_price) AS avg_store_price FROM store_sales GROUP BY ss_item_sk ), web_price AS ( SELECT ws_item_sk, AVG(ws_list_price) AS avg_web_price FROM web_sales GROUP BY ws_item_sk ), price_variance AS ( SELECT i.i_category, i.i_item_id, i.i_product_name, COALESCE(sp.avg_store_price, 0) AS store_price, COALESCE(wp.avg_web_price, 0) AS web_price, ABS(COALESCE(sp.avg_store_price, 0) - COALESCE(wp.avg_web_price, 0)) AS price_variance, CASE WHEN COALESCE(sp.avg_store_price, 0) > COALESCE(wp.avg_web_price, 0) THEN 'Store Higher' WHEN COALESCE(sp.avg_store_price, 0) < COALESCE(wp.avg_web_price, 0) THEN 'Web Higher' ELSE 'Equal' END AS price_comparison FROM item i LEFT JOIN store_price sp ON i.i_item_sk = sp.ss_item_sk LEFT JOIN web_price wp ON i.i_item_sk = wp.ws_item_sk WHERE COALESCE(sp.avg_store_price, 0) > 0 OR COALESCE(wp.avg_web_price, 0) > 0 ), category_agg AS ( SELECT i_category AS category, COUNT(*) AS item_count, AVG(price_variance) AS avg_price_variance FROM price_variance GROUP BY i_category ), category_stats AS ( SELECT category, item_count, avg_price_variance, DENSE_RANK() OVER (ORDER BY avg_price_variance DESC) AS variance_rank FROM category_agg ), warehouse_sales AS ( SELECT w_warehouse_name, total_net_profit, RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM ( SELECT w.w_warehouse_name, SUM(ws.ws_net_profit) AS total_net_profit FROM web_sales ws JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk GROUP BY w.w_warehouse_name ) ws_agg ) SELECT cs.category, cs.item_count, cs.avg_price_variance, cs.variance_rank, ws.w_warehouse_name, ws.total_net_profit, ws.profit_rank FROM category_stats cs LEFT JOIN ( SELECT * FROM warehouse_sales WHERE profit_rank = 1 ) ws ON 1=1 ORDER BY cs.variance_rank LIMIT 10
